	int *arr = new int[n];
	for (int i = 0; i < n; i++)
		arr[i] = 0;
	int count = 0;
	for (int i = 0; i < n - 1; i++)
	{
		if (str[i] == str[i + 1])
		{
			arr[count] = 2;
			count++;
			i++;
		}
		else {
			arr[count] = 1;
			count++;
		}
	}
	if (str[n - 1] != str[n-2])
		arr[count] = 1;
	for (int i = 0; i < n; i++)
		cout << arr[i] << " ";

	if (n == 1)
	{
		cout << 3;
		return 0;
	}
	if (n == 2)
	{
		if (str[0] == str[1])
			cout << 6;
		else cout << 6;
		return 0;
	}
	if (n == 3)
	{
		if (arr[0] == 2 && arr[1] == 1)
			cout << 6;
		return 0;
	}
	long long ans = 0;
	if (arr[0] == 1)
		ans = 3;
	else ans = 6;
	long long mod = 1000000007;

	for (int i = 1; i < str.size(); i++)
	{
		if (arr[i] == 1 && arr[i - 1] == 1)
