char S[2][53];      //ドミノの敷き詰め方
long long DP;       //横iマスを塗り分ける場合の数
const long long MOD=1000000007;


int main() {
    int N;      //横のマス数
    cin >> N;
    for (int i=1; i<=N; ++i) cin >> S[0][i];
    for (int i=1; i<=N; ++i) cin >> S[1][i];
    //以上読み込み

    int x;      //現在のx座標,初期値によって変わる
    if (S[0][N] == S[1][N]) {
        x = 2;
        DP = 3;     //縦3通り
    }
    else {
        x = 3;
        DP = 6;     //横横で3*2通り
    }
    //以上初期値の場合分け

    while (x < N) {

        if (S[0][x] == S[1][x]) {       //縦の右に
            if (S[0][x-1] == S[1][x-1]) //縦が並ぶなら *2
                DP = 2 * DP % MOD;      //横が並ぶなら *1
            ++x;                        
        }

        else {                          //横の右に
            if (S[0][x-1] == S[1][x-1]) //縦が並ぶなら横の上下の入れ替えで *2
                DP = 2 * DP % MOD;            
            else 
                DP = 3 * DP % MOD;      //横が並ぶなら *(2+1)
            x += 2;
        }
    }

    cout << DP << endl;
    return 0; 
}

