const int MOD=1000000007;

int main(){
  int N; cin >> N;
  string S1,S2; cin >> S1 >> S2;
  int before=0;
  int pos=0;
  long long result=1;
  while(pos<N){
    if(S1[pos]==S2[pos]){
      if(before==0){
        result*=3;
      }else if(before==1){
        result*=2;
      }else{
        result*=1;
      }
      result%=MOD;
      before=1;
      pos++;
    }else{
      if(before==0){
        result*=6;
      }else if(before==1){
        result*=2;
      }else{
        result*=3;
      }
      result%=MOD;
      before=2;
      pos+=2;
    }
  }
  cout << result << endl;
}

