	{
		if (n < r || n <= 0 || r < 0)
		{
			return 0;
		}
		r = min(r, n - r);
		lint a = start;
		for (size_t i = n; i >= n - r + 1; i--)
		{
			a *= i;
			a %= mod;
		}

		a *= getModInv(FactMod(r));
		a %= mod;
		return a;
	}

