	ll tot = 1;
	int last = -1;
	FOR(i,n){
		if(last == -1){
			if(s1[i] == s2[i]){
				tot *= 3;
				last = 1; // col
			}else{
				i++;
				tot *= 6;
				last = 2; // row
			}
		}else if(last == 1){
			if(s1[i] == s2[i]){
				tot *= 2;
				tot %= MOD;

			}else{
				i++;
				tot *= 2;
				tot %= MOD;
				last = 2;
			}
		}else{
			if(s1[i] == s2[i]){
				last = 1;
			}else{
				i++;
				tot *=3;
				tot %= MOD;

			}
		}
		tot %= MOD;
	}
	cout << tot%MOD << endl;
}

