int main(){
    Init();
    ll n, ans = 0, pre = 0; cin >> n;
    vector<string> s(2);
    cin >> s[0] >> s[1];

    // ブロックの置き方は2通りしかないため、左から順に処理していく
    // [置き方1] 縦に1個（2*1マス）
    //　最も左なら3通り、置き方1の後なら2通り、置き方2の後なら1通り
    // [置き方2] 横に2個（2*2マス）
