        if(s[0][i] == s[1][i]){
            // 最も左の場合
            if(i == 0){
                ans = 3;
                pre = 1;
            }
            // 置き方1の後の場合
            else if(pre == 1){
                ans = (ans*2)%MODV;
                pre = 1;
            }
            // 置き方2の後の場合
            else{
                ans = ans*1;
                pre = 1;
            }
        }
        // 置き方2の場合
        else{
            // 最も左の場合
            if(i == 0){
                ans = 6;
                pre = 2;
            }
            // 置き方1の後の場合
            else if(pre == 1){
                ans = (ans*2)%MODV;
                pre = 2;
            }
            // 置き方2の後の場合
            else{
                ans = (ans*3)%MODV;
                pre = 2;
            }
            // 2個分読み取るのでその分iを増やす
            i++;
        }
    }

    // 答えの出力
    cout << ans << endl; 
}

