using namespace std;

const long MOD = 1e9 + 7;

long pow(long n, long k) {
    long res = 1;
    while (k) {
        if (k & 1) res = res * n % MOD;
        n = n * n % MOD;
        k >>= 1;
    }
    return res;
}

int main() {
    int n;
    string sa, sb;
    cin >> n;
    cin >> sa >> sb;
    long res = 1;
    int last = 0;
    for (int i = 0; i < n; ++i) {
        if (sa[i] == sb[i]) {
            assert(!((i - last) & 1));
            int len = (i - last) >> 1;
            if (len == 0) {
                if (last == 0)
                    res = res * 3;
                else
                    res = (res << 1) % MOD;
            } else {
                if (last == 0)
                    res = res * 6;
                else
                    res = (res << 1) % MOD;
                res = res * pow(3, len - 1) % MOD;
            }
            last = i + 1;
        }
    }
    int len = (n - last) >> 1;
    if (len) {
        if (last == 0)
            res = res * 6;
        else
            res = (res << 1) % MOD;
        res = res * pow(3, len - 1) % MOD;
    }
    cout << res << endl;

    return 0;
}

