#include <iostream>
#include <vector>
#include <string>

using namespace std;

string label(vector<string> s) {
  string label_str;
  for (int i = 0; i < s[0].size(); i++) {
    if (s[0][i] == s[1][i])
      label_str += "T";  // `T` stands for Tate.
    else {
      label_str += "Y";  // `Y` stands for Yoko.
      i++;
    }
  }
  return label_str;
}

unsigned long long calculator(string label) {
  int patterns;
  string last_label;
  if (label[0] == 'Y') {
    patterns = 2 * 3;  // i,e: 2 * 3C2
    last_label = "Y";
  } else {
    patterns = 1 * 3;  // i,e: 1 * 3C1
    last_label = "T";
  }

  for (int i = 1; i < label.size(); i++) {
    if (label[i] == 'T') {
      if (last_label == "T")
        patterns *= 2;  // TT
      else if (last_label == "Y")
        patterns *= 1;  // YT
      last_label = "T";
    } else if (label[i] == 'Y') {
      if (last_label == "Y")
        patterns *= 3;  // YY
      else if (last_label == "T")
        patterns *= 2;  // TY
      last_label = "Y";
    }
  }
  return patterns;
}

int main() {
  int N;
  cin >> N;
  vector<string> S = vector<string>(2);
  cin >> S[0];
  cin >> S[1];
  string label_str = label(S);
  cout << label_str << endl;

  unsigned long long coloring_patterns = calculator(label_str);
  coloring_patterns %= 1000000007;
  cout << coloring_patterns << endl;
}

