				dp[i] = dp[i - 1] % modd;
			}
			else {
				dp[i] = (dp[i - 1] % modd) * 2;
			}
			++i; flag = 0;
		}
		else {
			if (flag) {
				dp[i] = (dp[i - 1] % modd) * 3;
			}
			else {
				dp[i] = (dp[i - 1] % modd) * 2;
			}
			dp[i + 1] = dp[i] % modd;
			i += 2; flag = 1;
		}
	}
	cout << dp[n - 1] % modd << endl;
	return 0;
}

