class Board {
    vector<vector<char>> board;
    vector<vector<int>> variations;

public:
    Board(int n) {
        board = vector<vector<char>>(n, vector<char>(2));
        variations = vector<vector<int>>(n, vector<int>(2));
    }

    void set(int x, int y, char color) {
        board[x][y] = color;
    }

    void setVariation(int x, int y, int variation) {
        variations[x][y] = variation;
    }

    char get(int x, int y) {
        if (x == -1 || y == -1) {
            return '.';
        }
        if (x == board.size() || y == board[x].size()) {
            return '.';
        }
        return board[x][y];
    }

    bool isChild(int x, int y) {

        char c = get(x, y);
        char l = get(x - 1, y);
        char u = get(x, y - 1);

        return c == l || c == u;
    }

    bool isHorizontal(int x, int y) {
        assert(!isChild(x, y));
        return get(x, y) == get(x + 1, y);
    }

    bool isVertical(int x, int y) {
        assert(!isChild(x, y));
        return get(x, y) == get(x, y + 1);
    }


    bool isLeftHorizontal(int x, int y) {
        char lu = get(x - 1, y);
        char ld = get(x - 1, y + 1);
        return lu != ld;
    }

    int getVariation(int x, int y) {
        return variations[x][y];
    }
};

struct mint {
    ll x; // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}

    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};


