ll fact[2005];
void factorials() {
	fact[0] = 1;
	for(ll i = 1; i <= 2002; i++) {
		fact[i] = (i * fact[i - 1]) % mod;
	}
} 

ll nCr(ll n, ll r) {
	if(r > n) {
		return 0;
	}
	ll result = fact[n];
	result = modDivide(result, fact[r], mod);
	return modDivide(result, fact[n - r], mod);
}

