using namespace std;
#define MOD 1000000007

int N;
string S1, S2;

int dp[52][3][3];
int solve(int now, int up, int down) {
	if (now == N) return 1;
	if (dp[now][up][down] != -1) return dp[now][up][down];
	if (S1[now] == S2[now]) {
		if (up != down)
			return dp[now][up][down] = ( solve(now + 1, (up + down) * 2 % 3, (up + down) * 2 % 3) )%MOD;
		else
			return dp[now][up][down] = ( solve(now + 1, (up + 1) % 3, (up + 1) % 3)
				+ solve(now + 1, (up + 2) % 3, (up + 2) % 3) )%MOD;
	}
	else {
		if (up == down)
			return dp[now][up][down] = (solve(now + 2, (up + 2) % 3, (down + 1) % 3) + solve(now + 2, (up + 1) % 3, (down + 2) % 3)) % MOD;
		else
			return dp[now][up][down] = (solve(now + 2, down, up) + solve(now + 2, down, (up + down) * 2 % 3) + solve(now + 2, (up + down) * 2 % 3, up)) % MOD;
	}
}

int main() {
	cin >> N;
	cin >> S1 >> S2;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < 3; j++) {
			for (int k = 0; k < 3; k++) {
				dp[i][j][k] = -1;
			}
		}
	}

	if (S1[0] == S2[0]) {
		cout << (solve(1, 0, 0) + solve(1, 1, 1) + solve(1, 2, 2)) % MOD << endl;
	}
	else {
		cout << (solve(2, 0, 1) + solve(2, 1, 2) + solve(2, 2, 0)
			+ solve(2, 1, 0) + solve(2, 2, 1) + solve(2, 0, 2)) % MOD << endl;
	}
}

