		for(int j=0;j<3;++j) for(int k=0;k<3;++k){
			if(S1[i] == S2[i] && j != k) continue;
			if(S1[i] != S2[i] && j == k) continue;
			for(int r=0;r<3;++r) for(int t=0;t<3;++t){
				if(S1[i-1] == S2[i-1] && r != t) continue;
