				if(S2[i] == S2[i-1] && t != k) continue;
				if(S2[i] != S2[i-1] && t == k) continue;
				dp[i][j][k] += dp[i-1][r][t];
			}
			dp[i][j][k]%=MOD;
		}
	}
	LL ans = 0;
	for(int j=0;j<3;++j) for(int k=0;k<3;++k) Ad(ans, dp[N-1][j][k]);
