vector<vector<int>> color;
vector<vector<char>> S;
int N;
long long bfs(int a, int b) {
    bool flag; //縦
    if(a == 0) {
        if(S[a][b] == S[a + 1][b]) {
            flag = true;
        } else {
            flag = false;
        }
    } else {
        if(S[a][b] == S[a - 1][b]) {
            flag = true;
        } else {
            flag = false;
        }
    }
    set<int> st{-1, 0, 1, 2};
    if(flag) {
        //縦のとき
        if(b > 0) {
            st.erase(color[0][b - 1]);
            st.erase(color[1][b - 1]);
        }
    } else {
        //横の時
        if(b > 0) {
            st.erase(color[a][b - 1]);
        }
        st.erase(color[abs(1 - a)][b]);
    }
    st.erase(-1);
    int variety = st.size();
    // cout << a << ":" << b << endl;
    if(flag) {
        if(b == N - 1) {
            return variety;
        }
        //縦
        color[0][b] = *st.begin();
        color[1][b] = *st.begin();

        return variety * bfs(0, b + 1) % MOD;
    } else {
        if(b == N - 1) {
            return variety;
        }
        //横
        color[a][b] = *st.begin();
        color[a][b + 1] = *st.begin();
        if(a == 0) {
            return variety * bfs(1, b);
        } else {
            return variety * bfs(0, b + 1) % MOD;
        }
    }
}

int main() {
    cin >> N;
    color.resize(2);
    S.resize(2);
    REP(i, 2) {
        color[i].resize(N);
        S[i].resize(N);
    }
    for(int i = 0; i < N; i++) {
        cin >> S[0][i];
    }
    for(int i = 0; i < N; i++) {
        cin >> S[1][i];
    }

    REP(i, 2) {
        REP(j, N) { color[i][j] = -1; }
    }
    cout << bfs(0, 0) << endl;
    return 0;
}

