using namespace std;
constexpr uint64_t mod = 1e9 + 7;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  int n;
  string s, t;
  cin >> n >> s >> t;
  if (n == 1) {
    cout << "3\n";
    return 0;
  }

  // bpat: 0 -> |
  // bpat: 1 -> =
  int bpat = s[0] == s[1];
  int64_t ans = bpat == 0 ? 3 : 6;
  int i;
  for (i = 1 + bpat; i < n - 1; ++i) {
    if (s[i] == s[i + 1]) {
      if (bpat == 0) {  // |=
        ans = (ans * 2) % mod;
      } else {          // ==
        ans = (ans * 3) % mod;
      }
      ++i;
      bpat = 1;
    } else {
      if (bpat == 0) {  // ||
        ans = (ans * 2) % mod;
      } else {  // =|
        // do nothing, we must select just one color which not used before.
      }
      bpat = 0;
    }
  }
  if (i == n - 1) {
    if (bpat == 0) {  // ||
      ans = (ans * 2) % mod;
    } else {  // =|
      // do nothing
    }
  }
  cout << ans << "\n";
}

