namespace task{

const int N=60;
const int base=1e9+7;
int dp[N][3][3];
char s1[N],s2[N];
int n;

void solve()
{
    scanf("%d",&n);
    scanf("%s%s",&s1,&s2);
    for(int i=0;i<3;++i)
        for(int j=0;j<3;++j)
    {
        if((s1[0]==s2[0]) ^ (i == j))continue;
        dp[0][i][j]=1;
    }
    for(int i=0;i<n-1;++i)
        for(int c1=0;c1<3;++c1)
          for(int c2=0;c2<3;++c2)
    {
        if(!dp[i][c1][c2])continue;
        for(int nc1=0;nc1<3;++nc1)
            for(int nc2=0;nc2<3;++nc2)
        {
            if((s1[i] == s1[i+1])^(c1 == nc1))continue;
            if((s2[i] == s2[i+1])^(c2 == nc2))continue;
            if((s1[i+1] == s2[i+1])^(nc1 == nc2))continue;
            dp[i+1][nc1][nc2]=addmod(dp[i+1][nc1][nc2],dp[i][c1][c2],base);
        }
    }
    int ans=0;
    for(int c1=0;c1<3;++c1)
        for(int c2=0;c2<3;++c2)
          ans=addmod(ans,dp[n-1][c1][c2],base);
    printf("%d\n",ans);
}}

int main(void)
{

    task::solve();
}

