lli getAns(lli n, string s1, string s2){
    lli res = 1;
    for(lli i = 0; i < n; i++){
        if(i == 0){
            if(s1[i] == s2[i]) res = ((res % NUM) * 3) % NUM;
            else{
                res = ((res % NUM) * 6) % NUM;
                i++;
            }
        }else{
            if(s1[i - 1] == s2[i - 1]){
                res = ((res % NUM) * 2) % NUM;
                i += (s1[i] != s2[i]);
            }else{
                if(s1[i] != s2[i]){
                    res = ((res % NUM) * 3) % NUM;
                    i++;
                }
            }
        }
    }
    return res;
}

