void solve(long long N, std::vector<std::string> S){
    LL ans = S[0][0] == S[1][0] ? 3 : 6;
    int idx = S[0][0] == S[1][0] ? 1 : 2;
    bool prevI = S[0][0] == S[1][0];
    while(idx<N){
        if(S[0][idx] == S[1][idx]) {
            if(prevI) ans *= 2;
            idx++;
            prevI = true;
        } else {
            if(prevI) ans *= 2;
            else ans *= 3;
            idx += 2;
            prevI = false;
        }

        ans %= MOD;
    }

    cout << ans << endl;
}

