      } else {
        is_pre_checked = true;
      }
    }
  }

  ll ans = (vt[0] == VERT) ? 3 : 6;
  ll M = vt.size();
  for (ll i = 1; i < M; i++) {
    ans = (ans * get_num_type(vt[i-1], vt[i])) % MOD;
  }

  print(ans);
  return;
}

