int solve(int column, vector<int> colors, const vector<string>& g) {
        if (dp.count({column, colors})) return dp[{column, colors}];
        if (column < 0) return 1;
        int ans = 0;
        if (g[0][column] == g[1][column]) {
                for (int i = 0; i < 3; i++) {
                        if (!count(all(colors), i)) {
                                ans += solve(column - 1, {i}, g);
                                ans %= MOD;
                        }
                }
        } else {
                for (int i = 0; i < 3; i++) {
                        for (int j = 0; j < 3; j++) {
                                if (i == j) continue;
                                if (colors.empty() || (colors.size() == 1 && i != colors.front() && j != colors.front()) ||
                                      (colors.size() == 2 && i != colors.front() && j != colors.back())) {
                                        ans += solve(column - 2, {i, j}, g);
                                        ans %= MOD;
                                }
                        }
                }
        }


        return dp[{column, colors}] = ans;
}


