			return solve(m + 1, (ans * 2) % 1000000007, 1);
		}
		if(before == 2){
			return solve(m + 1, ans, 1);
		}
		if(before == 0){
			return solve(m + 1, ans * 3, 1);
		}
	}
	else{
		if(before == 1){
			return solve(m + 2, (ans * 2) % 1000000007, 2);
		}
		if(before == 2){
			return solve(m + 2, (ans * 3) % 1000000007, 2);
		}
		if(before == 0){
			return solve(m + 2, ans * 6, 2);
		}
	}
}

