    dp[n][1][0][0] += dp[i][0][1][0];
    dp[n][1][0][0] += dp[i][0][0][1];
    dp[n][0][1][0] += dp[i][0][0][1];

    dp[n][0][0][1] += dp[i][1][1][0];
    dp[n][1][0][0] += dp[i][0][1][1];
    dp[n][0][1][0] += dp[i][1][0][1];
  } else {
    int n = i + 2;

    dp[n][1][1][0] += dp[i][0][0][0] * 2;
    dp[n][0][1][1] += dp[i][0][0][0] * 2;
    dp[n][1][0][1] += dp[i][0][0][0] * 2;

    dp[n][0][1][1] += dp[i][1][0][0] * 2;
    dp[n][1][0][1] += dp[i][0][1][0] * 2;
    dp[n][1][1][0] += dp[i][0][0][1] * 2;

    dp[n][1][1][0] += dp[i][1][1][0];
    dp[n][0][1][1] += dp[i][1][1][0];
    dp[n][1][0][1] += dp[i][1][1][0];
    dp[n][1][1][0] += dp[i][0][1][1];
    dp[n][0][1][1] += dp[i][0][1][1];
    dp[n][1][0][1] += dp[i][0][1][1];
    dp[n][1][1][0] += dp[i][1][0][1];
    dp[n][0][1][1] += dp[i][1][0][1];
    dp[n][1][0][1] += dp[i][1][0][1];

    i++;
  }

  mint ans = 0;
  rep(i, 8) ans += dp[N][(i & 4) >> 2][(i & 2) >> 1][i & 1];
  cout << ans << '\n';
}

