long long solve() {
  long long ans = 3;
  for(long long i = 0; i < n; ++i) {
    if(i == 0 && s[0][0] != s[1][0]) {
      ans = 6;
      ++i;
      continue;
    }
    if(i == 0) continue;
    if(s[0][i] == s[1][i]) {
      if(s[0][i - 1] == s[1][i - 1]) ans *= 2;
      ans %= N;
    }
    else {
      if(s[0][i] == s[1][i])
        ans *= 2;
      else
        ans *= 3;
      ans %= N;
      ++i;
    }
  }
  return ans;
}

