#define mod 1000000007

long long solve(int cur, int prev){
    if(cur >= N) return 1;
    bool vert = s[0][cur] == s[1][cur];
    long long res = 0;
    if(prev==-1){
        if(vert) res = 3*solve(cur+1, 0);
        else res = 6*solve(cur+2, 1);
    }else if(prev==0){ //up
        if(vert) res = 2*solve(cur+1, 0);
        else res = 2*solve(cur+2, 1);
    }else{ //l-r
        if(vert) res = solve(cur+1, 0);
        else res = 3*solve(cur+2, 1);
    }
    return res%mod;
}

