        dp[1][0][0] = dp[1][1][1] = dp[1][2][2] = 1;
        st = 2;
    }
    else {
        dp[2][0][1] = dp[2][0][2] = dp[2][1][0] = dp[2][1][2] = dp[2][2][0] = dp[2][2][1] = 1;
