            for (int k = 0; k <= 2; ++k) {
                for (int p1 = 0; p1 <= 2; ++p1)
                for (int p2 = 0; p2 <= 2; ++p2)
                    if (k != p1 && k != p2)
                        dp[i][k][k] = (dp[i][k][k] + dp[i - 1][p1][p2]) % MOD;
            }
        } else {
            for (int p1 = 0; p1 <= 2; ++p1)
            for (int p2 = 0; p2 <= 2; ++p2)
            for (int q1 = 0; q1 <= 2; ++q1)
