int N;
int G[52][52],F[52][52];
bool used[52];

int ch(char a) {
    int b = a - 'a';
    if (b >= 0 && b < 26) return b;
    return a - 'A' + 26;
}

int rk(int u) {
    int res = 0;
    for (int i = 0; i < N; i++) {
        if (G[u][i] == 1) res++;
    }
    return res;
}

int changed(int u) {
    int res = 0;
    for (int i = 0; i < N; i++) {
        if (G[u][i] == 0 && F[u][i] == 1) res++;
    }
    return res;
}

void del(int u) {
    for (int i = 0; i < N; i++) G[u][i]=G[i][u] = 0;
}


int main() {
    cin >> N;
    string S1, S2; cin >> S1 >> S2;

    for (int i = 0; i < N-1; i++) {
        if (S1[i] != S1[i+1]) 
        G[ch(S1[i])][ch(S1[i+1])] = G[ch(S1[i+1])][ch(S1[i])] = 1;
        if (S2[i] != S2[i+1]) 
        G[ch(S2[i])][ch(S2[i+1])] = G[ch(S2[i+1])][ch(S2[i])] = 1;
    }
    for (int i = 0; i < N; i++) {
        if (S1[i] != S2[i]) 
        G[ch(S1[i])][ch(S2[i])] = G[ch(S2[i])][ch(S1[i])] = 1;
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            F[i][j] = G[i][j];
        }
    }
    if (N == 1) {
        cout << 3 << endl; return 0;
    }


    int D = 1e9+7;
    int res = 1;
    for (int i = 0; i < N; i++) {
        int s1 = ch(S1[i]), s2 = ch(S2[i]);
        if (!used[s1]) { 
            res = (res * (3-changed(s1)))%D;
            del(s1);
            used[s1] = true;
        }
        if (!used[s2]) { 
            res = (res * (3-changed(s2)))%D;
            del(s2);
            used[s2] = true;
        }
    }
    cout << res << endl;
}

