#include <bits/stdc++.h>
#define endl '\n'

using namespace std;
const int MAXN = (60);
const int mod = (int)1e9 + 7;

int n;
string s1, s2;

void read()
{
	cin >> n;
	cin >> s1 >> s2;
}

int dp[MAXN][4];
int c[MAXN][16][16];

int rec(int len, int maskl, int maskr)
{	
	if(len == 0)
	{
		if(maskl == 1 || maskr == 1) return 1;	
		return (maskl & maskr) == 0;
	}

	int &memo = c[len][maskl][maskr];
	if(memo != -1) return memo;

	memo = 0;
	if(maskl != 1 && __builtin_popcount(maskl) == 1)
	{
		for(int col1 = 1; col1 <= 3; col1++)
			for(int col2 = 1; col2 <= 3; col2++)	
				if(col1 != col2)	
				{
					int new_mask = (1 << col1) + (1 << col2);
					if(__builtin_popcount(new_mask & maskl) == 0)
						memo = (memo + rec(len - 2, new_mask, maskr)) % mod; 
				}

		return memo;
	}

	for(int col1 = 1; col1 <= 3; col1++)
		for(int col2 = col1 + 1; col2 <= 3; col2++)
		{
			int new_mask = (1 << col1) + (1 << col2);
			memo = (memo + rec(len - 2, new_mask, maskr)) % mod; 
		}

	return memo;
}

int C(int len, int L, int R) { return rec(len, (1 << L), (1 << R)); }

void solve()
{
	memset(c, -1, sizeof(c));

	dp[0][0] = 1;

	int last = 0, len = 0;
	for(int i = 1; i <= n; i++)
	{
		bool is_up = (s1[i - 1] == s2[i - 1]); 
		if(is_up)
		{
			for(int col = 0; col <= 3; col++)
				for(int col2 = 1; col2 <= 3; col2++)
					dp[i][col2] = ((long long)dp[i][col2] + dp[last][col] * 1ll * C(len, col, col2)) % mod; 

			last = i;
			len = 0;
		}
		else len++;
	}

	for(int col = 0; col <= 3; col++)
		for(int col2 = 0; col2 <= 3; col2++)
			dp[n + 1][col2] = ((long long)dp[n + 1][col2] + dp[last][col] * 1ll * C(len, col, col2)) % mod; 

	cout << dp[n + 1][0] << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

