int solve(int now, int up, int down) {
	if (now == N) return 1;
	if (S1[now] == S2[now]) {
		if (up != down)
			return ( solve(now + 1, (up + down) * 2 % 3, (up + down) * 2 % 3) )%MOD;
		else
			return ( solve(now + 1, (up + 1) % 3, (up + 1) % 3)
				+ solve(now + 1, (up + 2) % 3, (up + 2) % 3) )%MOD;
	}
	else {
		return (  solve(now + 2, (up + 2) % 3, (down + 1) % 3) + solve(now + 2, (up + 1) % 3, (down + 2) % 3) ) % MOD;
	}
}

