            return ans = 6;
        }

        if (S1[i + 2] == S2[i + 2]) {
            ans = 2 * f(i + 2);
            ans %= MOD7;
            return ans;
        } else {
            return ans = (int)(3LL * f(i + 2) % MOD7);
        }
