void f(string s1, string s2, int p, bool flag){
  if(p >= s1.length()) return;
  if(s1[p] == s2[p]){
    if(flag){
      ans *= 2;
      ans %= mod;
      f(s1, s2, p + 1, flag);
    }else{
      flag = true;
      f(s1, s2, p + 1, flag);
    }
  }else{
    if(flag){
      ans *= 2;
      ans %= mod;
      flag = false;
      f(s1, s2, p + 2, flag);
    }else{
      ans *= 3;
      ans %= mod;
      f(s1, s2, p + 2, flag);
    }
  }
}

