ll dp[55];

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N >> s[0] >> s[1];

  if (s[0][0] == s[1][0]) {
    dp[0] = 3;
  } else {
    dp[0] = dp[1] = 6;
  }
  for (int i = 0; i < N;) {
    if (s[0][i] == s[1][i]) {
      if (s[0][i+1] == s[1][i+1]) {
        dp[i+1] = dp[i] * 2;
        dp[i+1] %= MOD;
        i++;
      } else {
        dp[i+1] = dp[i] * 2;
        dp[i+1] %= MOD;
        dp[i+2] = dp[i] * 2;
        dp[i+2] %= MOD;
        i++;
      }
    } else {
      if (s[0][i+2] == s[1][i+2]) {
        dp[i+2] = dp[i];
        dp[i+2] %= MOD;
        i += 2;
      } else {
        dp[i+2] = dp[i] * 3;
        dp[i+2] %= MOD;
        dp[i+3] = dp[i] * 3;
        dp[i+3] %= MOD;
        i += 2;
      }
    }
  }
