    int pre_pattern{2}, reaction[3][2]{{3, 1}, {2, 2}, {6, 3}};
    for (int i = 0; i < n; i++)
    {
        int now_pattern = s[0][i] == s[1][i];
        pattern_sum = pattern_sum * reaction[pre_pattern][now_pattern] % mod;
