bool out(int x, int y){
    if(x < 0 || x >= n || y < 0 || y >= 2) return true;
    return false;
}

set<char> tansaku(int x, int y, set<char> S){
    for(int d = 0; d < 4; d++){
        int nx = x + dx4[d];
        int ny = y + dy4[d];
        if(out(nx, ny))continue;
        if(used[ny][nx]) S.insert(s[ny][nx]);
    }
    return S;
}

void dfs(int x, int y){
    int ax, ay;
    queue<P> que;
    if(used[y][x]) return;
    used[y][x]++;
    char c = s[y][x];
    for(int d = 0; d < 4; d++){
        int nx = x + dx4[d];
        int ny = y + dy4[d];
        if(out(nx, ny))continue;
        if(s[ny][nx] == c){
            used[ny][nx]++;
            ax = nx, ay = ny;
        }
        if(!used[ny][nx]) que.push(mp(nx, ny));
    }
    for(int d = 0; d < 4; d++){
        int nx = ax + dx4[d];
        int ny = ay + dy4[d];
        if(out(nx, ny))continue;
        if(!used[ny][nx]) que.push(mp(nx,ny));
    }
    set<char> S;
    S = tansaku(x, y, S);
    S = tansaku(ax, ay, S);
    int cnt = 4-S.size();
    ans = (ans * cnt) % mod;
    // cout  << idx << " x: " << x << " y: "<<  y << " ax: "<< ax << " ay: " << ay << " cnt: "<< cnt << endl;
    while(!que.empty()){
        P p = que.front();
        que.pop();
        int ux = p.fi, uy = p.se;
        dfs(ux, uy);
    }
    return;
}

