  std::vector<std::string> S(2);
  for (int i = 0; i < 2; i++) {
    std::cin >> S[i];
  }

  ll ans = 1;
  int i = 0;
  if (S[0][0] == S[1][0]) {
    ans *= 3;
    i = 1;
  } else {
    ans *= 6;
    i = 2;
  }

  for (; i < N; i++) {
    if (S[0][i] == S[1][i]) {
      ll multi = (S[0][i - 1] == S[1][i - 1]) ? 2 : 1;
      ans = mod(ans * multi, MOD);
      continue;
    }

    ll multi = (S[0][i - 1] == S[1][i - 1]) ? 2 : 3;
    ans = mod(ans * multi, MOD);
    i++;
  }

  put(ans);
  return 0;
}

