class D {
	int n;
	string s;
	const int MOD{ 1000000007 };
public:
	D()
	{
		cin >> n >> s;
	}
	void solve()
	{
		vi v;

		int i{ 0 };
		while (i < n)
		{
			if (i == n - 1)
			{
				v.PB(1);
				++i;
			}

			else if (s[i] == s[i + 1])
			{
				v.PB(0);
				i += 2;
			}

			else
			{
				v.PB(1);
				i++;
			}
		}


		ll ans;
		int last{ v.back() };
		if (last)
			ans = 3;
		else
			ans = 6;
		v.pop_back();

		while (!v.empty())
		{
			if (last)
			{
				ans = ans * 2 % MOD;
				last = v.back();
				v.pop_back();
			}

			else
			{
				if (!v.back())
					ans = ans * 3 % MOD;

				last = v.back();
				v.pop_back();
			}

		}

		cout << ans << endl;
	}
};


int main()
{
	D solution;
	solution.solve();

	return 0;
}

