ll paint(int i, int c0, int c1)
{
    if (dp[i][c0][c1] != -1) {
        return dp[i][c0][c1];
    }
    if (i == N - 1) {
        return dp[i][c0][c1] = 1;
    }
    if (c0 == c1) {
        if (s1[i + 1] == s2[i + 1]) {
            return dp[i][c0][c1] = (paint(i + 1, (c0 + 1) % 3, (c0 + 1) % 3) + paint(i + 1, (c0 + 2) % 3, (c0 + 2) % 3)) % MOD;
        } else {
            return dp[i][c0][c1] = (paint(i + 1, (c0 + 1) % 3, (c0 + 2) % 3) + paint(i + 1, (c0 + 2) % 3, (c0 + 1) % 3)) % MOD;
        }
    } else {
        if (s1[i] == s1[i + 1]) {
            return dp[i][c0][c1] = paint(i + 1, c0, c1);
        } else {
            int c2 = 3 - (c0 + c1);
            if (s1[i + 1] == s2[i + 1]) {
                return dp[i][c0][c1] = paint(i + 1, c2, c2);
            } else {
                return dp[i][c0][c1] = ((paint(i + 1, c1, c0) + paint(i + 1, c1, c2)) % MOD + paint(i + 1, c2, c0)) % MOD;
            }
        }
    }
}

