int dp[52][4][4];

int f(int k, int a, int b)
{
    if (k == n) return 1;
    if (dp[k][a][b] != -1) return dp[k][a][b];
    int sol = 0;
    if (s[0][k] == s[1][k])
    {
        for (int i = 0; i < 3; ++i)
            if (i != a && i != b)
                adds(sol, f(k + 1, i, i));
    }
    else
    {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                if (i != j && i != a && j != b)
                    adds(sol, f(k + 2, i, j));
    }
    return dp[k][a][b] = sol;
}

