  std::array<std::string, 2> S;
  std::copy_n(std::istream_iterator<std::string>(std::cin), 2, S.begin());

  std::vector<std::int_fast32_t> preprocessed;
  for (std::int_fast32_t i = 0; i < N;) {
    if (S[0][i] == S[1][i]) {
      preprocessed.push_back(0);
      ++i;
    } else {
      preprocessed.push_back(1);
      i += 2;
    }
  }

  tools::int_mod<P> answer(1);
  std::int_fast32_t prev_state = 2;
  static std::array<std::array<tools::int_mod<P>, 2>, 3> table({
    std::array<tools::int_mod<P>, 2>({tools::int_mod<P>(2), tools::int_mod<P>(2)}),
    std::array<tools::int_mod<P>, 2>({tools::int_mod<P>(1), tools::int_mod<P>(3)}),
    std::array<tools::int_mod<P>, 2>({tools::int_mod<P>(3), tools::int_mod<P>(6)})
  });
  for (const std::int_fast32_t& state : preprocessed) {
    answer *= table[prev_state][state];
    prev_state = state;
  }

  std::cout << answer << std::endl;
