int M[2][52];

ll func ( int N )
{
  ll ans;
  int pos,pre; // 縦:pre = 0, 横:pre = 1

  if ( M[0][0] == M[1][0] ) ans = 3,pos = 1,pre = 0;
  else ans = 6,pos = 2,pre = 1;

  while ( pos < N ) {
    if ( pre == 1 ) {
      if ( M[0][pos] == M[1][pos] ) {
         pos++; pre = 0;
      } else {
        pos += 2; ans *= 3; pre = 1;
      }
    } else {
      if ( M[0][pos] == M[1][pos] ) {
        ans *= 2; ++pos; pre = 0;
      } else {
        ans *= 2; pos += 2; pre = 1;
      }
    }
  }

  return ans % MAXN;
}

