int main()
{
  int N; scanf("%d", &N);
  string s, t;
  cin >> s >> t;
  ll ans = (s[0] == t[0]) ? 3 : 6;
  // 0: vertical
  // 1: horizontal
  int prev = (s[0] == t[0]) ? 0 : 1;
  for (int i = prev + 1; i < N; ) {
    if (s[i] == t[i]) {
      // => vertical
      if (prev == 0) {
        // vertical => vertical
        ans *= 2;
      }
      else {
        // horizontal => vertical
        prev = 0;
      }
      ++i;
    }
    else {
      // => horizontal
      if (prev == 0) {
        // vertical => horizontal
        ans *= 2;
        prev = 1;
      }
      else {
        // horizontal => horizontal
        ans *= 3;
      }
      i += 2;
    }
    ans %= MOD;
  }
  printf("%lld\n", ans);
  return 0;
}

