// Class ModInteger<MOD>
template <lint mod>
class ModInteger {
    public:
    lint val;

    // Constructor
    ModInteger(): val(0) {}
    ModInteger(lint ival): val(ival >= 0? ival%mod: mod - (-ival)%mod) {}

    // Comparators
    bool operator !() {return val == 0;}
    bool operator <(ModInteger that) {return val < that.val;}
    bool operator >(ModInteger that) {return val > that.val;}
    bool operator <=(ModInteger that) {return val <= that.val;}
    bool operator >=(ModInteger that) {return val >= that.val;}
    bool operator ==(ModInteger that) {return val == that.val;}
    bool operator !=(ModInteger that) {return val != that.val;}

    // Basic operations
    ModInteger operator ++() {val++; return *this;}
    ModInteger operator --() {val--; return *this;}

    ModInteger& operator +=(ModInteger that) {val = (val + that.val)%mod; return *this;}
    ModInteger& operator -=(ModInteger that) {val = ((val - that.val)%mod + mod)%mod; return *this;}
    ModInteger& operator *=(ModInteger that) {val = (val*that.val)%mod; return *this;}
    ModInteger& operator /=(ModInteger that) {
        lint inv = that.val, rem = 1, power = mod - 2;
        while (power > 1) {if (power%2) rem = (rem*inv)%mod; inv = (inv*inv)%mod; power /= 2;}
        inv = (rem*inv)%mod;
        val = (val*inv)%mod;
        return *this;
    }

    ModInteger operator +(ModInteger that) {return ModInteger(*this) += that;}
    ModInteger operator -(ModInteger that) {return ModInteger(*this) -= that;}
    ModInteger operator *(ModInteger that) {return ModInteger(*this) *= that;}
    ModInteger operator /(ModInteger that) {return ModInteger(*this) /= that;}

    ModInteger& operator %=(ModInteger that) {val = val%that.val; return *this;}
    ModInteger operator %(ModInteger that) {return ModInteger(*this) %= that;}
}; using mint = ModInteger<MOD>;

