// Basic functions (be careful of overflowing!)
template <typename Tp>
Tp gcd(Tp m, Tp n) {
    if (!m || !n) {cout << "GCD error: zero inputed" << endl; return 0;}
    else if (!(m%n)) return n;
    else return gcd(n, m%n);
}
template <typename Tp>
Tp lcm(Tp m, Tp n) {
    if (!m || !n) {cout << "LCM error: zero inputed" << endl; return 0;}
    else return m*n/gcd(m, n);
}
template <typename Tp1, typename Tp2>
Tp1 ipow(Tp1 a, Tp2 p) {// For integers
    if (p < 0) {cout << "Power error: a minus number inputed" << endl; return 0;}
    else if (!p) return 1;
    Tp1 res = a, rem = 1;
    while (p > 1) {if (p%2) rem *= res; res *= res; p /= 2;}
    return rem*res;
}
template <typename Tp>
Tp fact(Tp n) {// Facorial: requires O(n)
    if (n < 0) {cout << "Factorial error: a minus number inputed" << endl; return 0;}
    else if (!n) return 1;
    else if (n == 1) return 1;
    else return n*fact(n - 1);
}
template <typename Tp>
void pfact(Tp n, map<Tp, int>& res) {// Prime factorization: requires O(sqrt(n))
    if (n <= 1) {cout << "Prime factorization error: cannot factorize an integer less than 2" << endl; return;}
    if (res.size()) cout << "Prime factorization warning: the map already contains some numbers" << endl;
    Tp pos = 2, pmax = n;
    while (pos*pos <= pmax) {if (!(n%pos)) {res[pos]++; n /= pos;} else pos++;}
    if (n != 1) res[n]++;
    return;
}
template <typename Tp>
Tp comb(Tp n, Tp r) {// Requires O(r)
    if (n < 0 || r < 0) {cout << "Combination error: a minus number inputed" << endl; return 0;}
    else {lint res = 1; rep(i, r) res *= (n - i)/(i + 1); return res;}
}

