	enum class Type {
		// a
		// a
		A,
		// bb
		// cc
		B,
		End
	};
	const auto NextDomino = [&cur, &s](){
		if(int(s[0].length()) == cur)
			return Type::End;
		if(s[0][cur] == s[1][cur]) {
			cur += 1;
			return Type::A;
		} else {
			// Type B
			cur += 2;
			return Type::B;
		}
	};
	uint64_t npat;
	Type prev = NextDomino();
	if(prev == Type::A) {
		npat = 3;
	} else {
		// (3P2)
		npat = 6;
	}

	for(;;) {
		const Type next = NextDomino();
		switch(next) {
			case Type::A:
				if(prev == Type::A) {
					// A -> A
					npat *= 2;
					npat %= Mod;
				} else {
					// B -> A
				}
				break;
			case Type::B:
				if(prev == Type::A) {
					// A -> B
					npat *= 2;
					npat %= Mod;
				} else {
					// B -> B
					npat *= 3;
					npat %= Mod;
				}
				break;
			case Type::End:
				goto END;
		}
		prev = next;
	}
	END:
	std::cout << npat << std::endl;
	return 0;
}

