using namespace std;

using I = ModInt<long long>;
const int C = 3;

int N;
string S1, S2;

using Memo=tuple<int,int,int>;
map<Memo, I> memo;
I dfs(int i, int u, int d) {
  if(i==N) return 1;
  auto m=Memo(i,u,d);
  if(memo.count(m)) return memo[m];
  I res;
  if(S1[i]==S2[i]) {
    set<int> ng;
    ng.emplace(u);
    ng.emplace(d);
    for(auto c=0; c<C; ++c) if(!ng.count(c)) res += dfs(i+1, c, c);
  } else {
    if(S1[i-1]==S1[i]) res += dfs(i+1, u, d);
    else
      for(auto u2=0; u2<C; ++u2) if(u2!=u)
        for(auto d2=0; d2<C; ++d2) if(d2!=d)
          if(u2!=d2) res += dfs(i+1, u2, d2);
  }
  return memo[m] = res;
}

int main() {
  cin >> N;
  cin >> S1 >> S2;
  I res;
  if(S1[0]==S2[0]) {
    for(auto c=0; c<C; ++c) res += dfs(1, c, c);
  } else {
    for(auto d=0; d<C; ++d) for(auto u=0; u<d; ++u) res += dfs(1, u, d) + dfs(1, d, u);
  }
  cout << res << endl;
}

