typedef long long ll;

ll start(const string a, const string b){
  if( a[0] == b[0] )
    return 3LL;
  else
    return 6LL;
}

ll transition(const string a, const string b, int i){
  if( a[i] == b[i] ){
    if( a[i+1] == b[i+1] ) return 2LL;
    else return 2LL;    
  }else{
    if( a[i+1] == b[i+1] ) return 1LL;
    else return 2LL;
  }
}

ll powmod(ll b, ll e, ll mod){
  if( e == 0 ) return 1LL;
  if( e % 2 == 0 ){
    ll t = powmod(b, e/2, mod);
    t = t*t%mod;
    return t;
  }else{
    ll t = powmod(b, e/2, mod);
    t = t*t%mod;
    t = t*b%mod;
    return t;
  }
}

ll pow(ll b, ll e){
  if( e == 0 ) return 1LL;
  if( e % 2 == 0 ){
    ll t = pow(b, e/2);
    t = t*t;
    return t;
  }else{
    ll t = pow(b, e/2);
    t = t*t;
    t = t*b;
    return t;
  }
}

