inline void solve(void){
  in(N);
  in(S,T);
  if(S[0]==T[0])ans=3,s=1;
  else ans=6,s=2;
  up(i,s,N-1){
    if(S[i-1]==T[i-1]){
      ans*=2,ans%=MOD;
      if(S[i]!=T[i])i++;
    }
    else if(S[i]!=T[i])ans*=3,ans%=MOD,i++;
  }
  out(ans);
}

