        if(i<N-1 && tab[0][i]==tab[0][i+1]){
            q.push(1);
            i++;
        }else{
            q.push(0);
        }
    }
    long long ans;
    int now=q.front(); q.pop();
    if(now==0){
        ans=3;
    }else{
        ans=6;
    }
    while(!q.empty()){
        int next=q.front(); q.pop();
        if(now==next){
            if(now==0){
                ans = (ans * 2)%mod;
            }else{
                ans = (ans * 3)%mod;
            }
        }else{
            if(now==0){
                ans = (ans * 2)%mod;
            }
            now=next;
        }
    }
    cout<<ans<<endl;
    return 0;
}

