            if (S[0][x-1] == S[1][x-1]) //縦が並ぶなら横の上下の入れ替えで *2
                DP = (2 * DP) % MOD;            
            else 
                DP = (3 * DP) % MOD;      //横が並ぶなら *(2+1)
            x += 2;
        }
    }

    cout << DP << endl;
