    if (pre_is_tate)
    {
        ans = 3;
    }
    else
    {
        ans = 6;
    }

    rep(i, N - 1)
    {
        bool is_tate = (S1[i + 1] == S2[i + 1]);
        if (i == 0 && S1[0] == S1[1])
            continue;
        if (!is_tate)
            i++;
        if (is_tate && pre_is_tate)
            ans *= 2;
        else if (!is_tate && pre_is_tate)
            ans *= 1;
        else if (is_tate && !pre_is_tate)
            ans *= 2;
        else if (!is_tate && !pre_is_tate)
            ans *= 3;
        pre_is_tate = is_tate;
    }

    cout << ans.x << endl;
