    if(s1[i]==s2[i]){
      if(t==0)ans*=2;
      i++;
      t = 0;
    }else{
      if(t==0)ans *= 2;
      else ans *= 3;
      i+=2;
      t = 1;
    }
  }

  cout << ans.x << endl;
}

