ll n;
vector<vector<ll>> done(2, vector<ll>(53)); //循環セールスマン問題みたいな考え方ができればいいよね
ll dfs(int u, vector<ll> memo)
{
    if (u == n)
    {
        return 1;
    }
    ll res = 0;
    if (pa[u] == 0 || pa[u] == 4)
    {
        memo[u] = 0;
        ll a = dfs(u + 1, memo);
        memo[u] = 1;
        ll b = dfs(u + 1, memo);
        memo[u] = 2;
        ll c = dfs(u + 1, memo);
        res = a + b + c;
        return res;
    }
    if (pa[u] == 1 || pa[u] == 3 || pa[u] == 5 || pa[u] == 6 || pa[u] == 8)
    {
        memo[u] = (memo[u - 1] + 1) % 3;
        ll a = dfs(u + 1, memo);
        memo[u] = (memo[u - 1] + 2) % 3;
        ll b = dfs(u + 1, memo);
        res = a + b;
        return res;
    }
    if (pa[u] == 7 || pa[u] == 9 || pa[u] == 10)
    {
        ll j = 0;
        for (int i = 0; i < 3; i++)
        {
            if (memo[u - 1] != i && memo[u - 2] != i)
            {
                j = i;
            }
        }
        memo[u] = j;
        return dfs(u + 1, memo);
    }
    return 0;
}

