int dp[52][3][3];
int solve(int now, int up, int down) {
	if (now == N) return 1;
	if (dp[now][up][down] != -1) return dp[now][up][down];
	if (S1[now] == S2[now]) {
		if (up != down)
			return dp[now][up][down] = ( solve(now + 1, (up + down) * 2 % 3, (up + down) * 2 % 3) )%MOD;
		else
			return dp[now][up][down] = ( solve(now + 1, (up + 1) % 3, (up + 1) % 3)
				+ solve(now + 1, (up + 2) % 3, (up + 2) % 3) )%MOD;
	}
	else {
