ll calc( long n, char* str0, char* str1, long before )
{
    if(n==0) {
        return 0;
    }
    else if(n==1) {
        return 3-before;
    }
    else {
        ll val = 0;
        if(str0[0]==str1[0]) val += (3-before)* calc(n-1, str0+1, str1+1, 1) % MOD;
        if(str0[0]!=str1[0] && before==2) val += 3* calc(n-2, str0+2, str1+2, 2) % MOD;
        if(str0[0]!=str1[0] && before==1) val += 2* calc(n-2, str0+2, str1+2, 2) % MOD;
        if(str0[0]!=str1[0] && before==0) val += 3*2* calc(n-2, str0+2, str1+2, 2) % MOD;
        return (val % MOD);
    }
}

