ll DP(ll x,ll y){
    if(x==n)return 1;
    ll &ret=dp[x][y];if(ret!=-1)return ret;
    ret=0;
    if(y==0){
        if(s[0][x]==s[1][x]){
            return ret=(3*DP(x+1,1))%mod;
        }
        else{
            return ret=(6*DP(x+1,2))%mod;
        }
    }
    if(y==1){
        if(s[0][x]==s[1][x])return ret=(2*DP(x+1,1))%mod;
        if(s[0][x]!=s[1][x])return ret=(2*DP(x+1,2))%mod;
    }
    if(y==2){
        if(s[0][x]==s[0][x-1])return ret=DP(x+1,y)%mod;
        if(s[0][x]!=s[1][x])return ret=(3*DP(x+1,2))%mod;
        return ret=DP(x+1,1)%mod;
    }
}
