#include <bits/stdc++.h>
using namespace std;

using u64 = uint64_t;

constexpr const u64 INVALID = UINT64_MAX;
constexpr const u64 MODNUM = 1000000007;

u64 count_way(vector<u64> &memo, array<string, 2> const &grid, unsigned a) {
    if (a >= grid[0].size()) return 1;
    if (memo[a] != INVALID) return memo[a];

    if (a == 0) {
        // 最初
        if (grid[0][a] == grid[1][a]) {
            // 縦。3通り。
            memo[0] = 3 * count_way(memo, grid, a+1);
        } else {
            // 横。6通り。
            memo[0] = 6 * count_way(memo, grid, a+2);
        }
    } else if (grid[0][a-1] == grid[1][a-1]) {
        // 前は縦
        if (grid[0][a] == grid[1][a]) {
            // 今回も縦。
            memo[a] = 2 * count_way(memo, grid, a+1);
        } else {
            // 今回は横。
            memo[a] = 2 * count_way(memo, grid, a+2);
        }
    } else {
        // 前は横
        if (grid[0][a] == grid[1][a]) {
            // 今回は縦。
            memo[a] = 1 * count_way(memo, grid, a+1);
        } else {
            // 今回も横。
            memo[a] = 3 * count_way(memo, grid, a+2);
        }
    }
    memo[a] %= MODNUM;
    return memo[a];
}

int main() {
    int N;
    array<string, 2> grid;
    cin >> N;
    cin >> grid[0] >> grid[1];
    vector<u64> memo(N, INVALID);
    cout << count_way(memo, grid, 0) << endl;
    return 0;
}

