    ll res = 1;
    ll i=0, W = S[0].length(), type=0;
    while(i < W){
        if(S[0][i]==S[1][i]){//* type1
            if(type == 0){
                res = (res * 3) % MOD;
            }
            else if(type == 1){
                res = (res * 2) % MOD;
            }
            type = 1;
            i++;
        }
        else {
            if(type == 0){
                res = (res * 6) % MOD;
            }
            else if(type == 1){
                res = (res * 2) % MOD;
            }
            else{
                res = (res * 3) % MOD;
            }
            type = 2;
            i += 2;
        }
    }
    cout << res << endl;
}

