vector<int> strcompress(string S, int N){
    int count = 1;
    char c = S[0];
    vector<int> vec; 
	rep(i, N-1){
		if(c == S[i+1]){
			count++;
		}else{
			vec.push_back(count);
			count = 1;
			c = S[i+1];
		}
	}
	vec.push_back(count);
    return vec;
}

