vector<int> decode(string s1, string s2) {
  vector<int> v;
  int i = 0;
  while (i < s1.size()) {
    if (s1[i] == s2[i])
      v.push_back(0), i += 1;
    if (i + 1 < s1.size() && s1[i] == s1[i + 1])
      v.push_back(1), i += 2;
  }
  return v;
}

