namespace abc051d {
	const int MAX_V = 101;
	ll cost[MAX_V][MAX_V];
	void warshallFloyd()
	{
		REP(i, N) {
			REP(j, N) {
				if (i == j) cost[i][j] = 0;
				else cost[i][j] = INT64_MAX;
			}
		}
		REP(k, N) {
			REP(i, N) {
				REP(j, N) {
					ll newCost = cost[i][k] + cost[k][j];
					if (cost[i][j] > newCost) {
						cost[i][j] = newCost;
					}
				}
			}
		}
	}
	void abc051d()
	{
		cin >> N >> M;
		vector<pair<pair<int, int>, int>> cs(M);
		REP(i, M) {
			int a, b, c; cin >> a >> b >> c;
			cost[a-1][b-1] = c;
			cost[b-1][a-1] = c;
			cs[i] = make_pair(make_pair(a-1, b-1), c);
		}
		warshallFloyd();

		int cnt = M;
		REP(m, M) {
			int a = cs[m].first.first, b = cs[m].first.second;
			bool del = false;
			REP(s, N) {
				if (cost[s][a] + cs[m].second == cost[s][b])
					del = true;
			}
			if (del) cnt--;
		}

		cout << cnt << endl;
	}
