void solve() {
    int n;
    cin >> n;
    VS s(2);
    cin >> s[0];
    cin >> s[1];
    VLL dp(n);
    if (n == 1) {
        cout << 3 << endl;
        return;
    }
    if (s[0][0] == s[1][0]) {
        dp[0] = 3;
        if (s[0][1] == s[1][1])
            dp[1] = 6;
    } else
        dp[1] = 6;

    REP(i, 2, n) {
        if (s[0][i] == s[1][i]) {
            if (s[0][i - 1] == s[1][i - 1])
                dp[i] = (dp[i - 1] * 2) % MOD;
            else
                dp[i] = dp[i - 1];
        } else if (s[0][i - 1] == s[0][i]) {
            if (s[0][i - 2] == s[1][i - 2])
                dp[i] = (dp[i - 2] * 2) % MOD;
            else
                dp[i] = (dp[i - 2] * 3) % MOD;
        }
    }
    cout << dp[n - 1] << endl;
}

