template <int mod>
struct ModInt
{
    ll x;

    constexpr ModInt(ll a = 0) noexcept
    {
        x = a % mod;
    }
    constexpr ll value() noexcept
    {
        return x;
    }
    constexpr const ll value() const noexcept
    {
        return x;
    }
    constexpr ModInt Pow(ll n) noexcept
    {
        ModInt<mod> ans(1), mul(x);
        for (int i = 0; i < 31; i++)
        {
            if (n & (1 << i))
            {
                ans *= mul;
            }
            mul *= mul;
        }
        return ans;
    }
    constexpr ModInt &operator+=(const ModInt y) noexcept
    {
        x += y.x;
        if (x >= mod)
        {
            x -= mod;
        }
        return *this;
    }
    constexpr ModInt &operator-=(const ModInt y) noexcept
    {
        if (x < y.x)
        {
            x += mod;
        }
        x -= y.x;
        return *this;
    }
    constexpr ModInt &operator*=(const ModInt y) noexcept
    {
        x = x * y.x % mod;
        return *this;
    }
    constexpr ModInt factorial() noexcept
    {
        int k = x;
        ModInt<mod> tmp(x);
        for (int i = 1; i < k; i++)
        {
            tmp *= ModInt<mod>(k - i);
        }
        return tmp;
    }
    constexpr ll inverse() noexcept
    {
        return this->Pow(mod - 2).x;
    }
    constexpr ModInt &operator/=(const ModInt y) noexcept
    {
        return (*this) * y.Pow(mod - 2);
    }
    constexpr ModInt operator+(const ModInt y) const noexcept
    {
        return ModInt(*this) += y;
    }
    constexpr ModInt operator*(const ModInt y) const noexcept
    {
        return ModInt(*this) *= y;
    }
    constexpr ModInt operator-(const ModInt y) const noexcept
    {
        return ModInt(*this) -= y;
    }
    constexpr ModInt operator/(const ModInt y) const noexcept
    {
        return *this /= y;
    }
    friend constexpr ostream &operator<<(ostream &os, const ModInt<mod> &x) noexcept
    {
        return os << x.value();
    }
};
using mint = ModInt<(int)(1000000007)>;
