				{
					dex.push_back(3);
				}
				else
				{
					dex.push_back(2);
				}
			}
			else
			{
				ans=(ans*3)%MOD;
				dex.push_back(3);
			}
		}
	}
	for(i=1;i<ind.size();i++)
	{
		if(ind[i]-ind[i-1]==1)
		{
			continue;
		}
		ans=(ans*dex[i-1]*2*((ind[i]-ind[i-1])/2))%MOD;
	}
	cout<<ans<<endl;
	return 0;
}

