const ll MOD = 1000000007;

/* typedef */

/* global variables */

ll dp[MAX_N][3][3];

/* subroutines */

inline bool match(char c0, char c1, int i, int j) {
  return (c0 == c1 && i == j) || (c0 != c1 && i != j);
}

/* main */

int main() {
  int n;
  string s0, s1;
  cin >> n >> s0 >> s1;

  for (int j0 = 0; j0 < 3; j0++)
    for (int j1 = 0; j1 < 3; j1++)
      dp[0][j0][j1] = match(s0[0], s1[0], j0, j1) ? 1 : 0;

  for (int i = 0; i < n - 1; i++)
    for (int j0 = 0; j0 < 3; j0++)
      for (int j1 = 0; j1 < 3; j1++)
	if (dp[i][j0][j1] > 0)
	  for (int k0 = 0; k0 < 3; k0++)
	    for (int k1 = 0; k1 < 3; k1++)
	      if (match(s0[i], s0[i + 1], j0, k0) &&
		  match(s1[i], s1[i + 1], j1, k1) &&
		  match(s0[i + 1], s1[i + 1], k0, k1))
		dp[i + 1][k0][k1] = (dp[i + 1][k0][k1] + dp[i][j0][j1]) % MOD;

  ll sum = 0;
  for (int j0 = 0; j0 < 3; j0++)
    for (int j1 = 0; j1 < 3; j1++)
      sum = (sum + dp[n - 1][j0][j1]) % MOD;

  printf("%lld\n", sum);
  return 0;
}

