ll calc(int i, ll sum) {
    if (i == N) return sum;
    if (s1[i - 1] == s2[i - 1]) {
        sum = sum * 2 % M;
        if (s1[i] == s2[i]) {
            return calc(i + 1, sum);
        } else {
            return calc(i + 2, sum);
        }
    } else {
        if (s1[i] == s2[i]) {
            return calc(i + 1, sum);
        } else {
            sum = sum * 3 % M;
            return calc(i + 2, sum);
        }
    }
}

