        } else if (!before && !current) {
            jou = 3;
        } else if (before && current) {
            jou = 2;
        } else if (itr-1 == blocks.begin()) {
            jou = 2;
        }
        //cout << " "  << jou;
        ans *= jou;
        before = current;
        if (ans > 1000000007)
            ans %= 1000000007;
    }

