const ll MOD = 1e9 + 7;
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    ll N; cin >> N;
    string S1,S2; cin >> S1 >> S2;
    ll ans = 1;
    ll i = 0;
    if(S1[i] == S2[i]){
        /*
         X
         X
         */
        ans *= 3;
        i++;
    }else{
        /*
         X X
         Y Y
         */
        ans *= 6;
        i+=2;
    }
    for(;i<N;){
        if(S1[i] == S2[i]){
            if(S1[i-1] == S2[i-1]){
                /*
                 X Y
                 X Y
                 */
                ans *= 2;
            }else{
                /*
                 YY X
                 ZZ X
                 */
                ans *= 1;
            }
            i++;
        }else{
            if(S1[i-1] == S2[i-1]){
                /*
                 Y XX
                 Y YY
                 */
                ans *= 2;
            }else{
                /*
                 AA XX
                 BB YY
                 */
                ans *= 3;
            }
            i += 2;
        }
        ans%=MOD;
    }
    cout << ans << endl;
	return 0;
}

