#include <iostream>

#define MAX_N 52
#define MOD   1000000007

int  N;
char S[2][MAX_N];

long solve() {
    bool prev = (S[0][0] == S[1][0]) ? true:false;
    int idx = (prev) ? 1:2;
    long res = (prev) ? 3:6;
    while (idx < N) {
        bool curr = (S[0][idx] == S[1][idx]) ? true:false;
        if (prev && curr) {
            res *= 2;
            res %= MOD;
            ++idx;
        } else if (prev && !curr) {
            res *= 2;
            res %= MOD;
            idx += 2;
        } else if (!prev && curr) {
            ++idx;
        } else {
            res *= 3;
            res %= MOD;
            idx += 2;
        }
        prev = curr;
    }
    return res;
}

