					ans = (ans * 3) % N;
				}
			}
		}
		else {
			if (s[i] == s[i + 1]) {
				if (s[i - 1] == t[i - 1]) {
					ans = (ans * 2) % N;
					i++;
				}
				else {
					ans = (ans * 3) % N;
					i++;
				}
			}
			else {
					if (s[i - 1] == t[i - 1]) {
						ans = ans * 2 % N;
					}
			}
		}
	}
