#ifdef D_TEST
	fgets(lc1Mass, sizeof(lc1Mass), szpFpT);
#else
	fgets(lc1Mass, sizeof(lc1Mass), stdin);
#endif

	// １文字目
	long long llPCnt;
	int liNo, liX;
	if (lc1Mass[0] == lc1Mass[1]) {			// 次と一致(横)
		llPCnt = 6;								// パターン数
		liNo = 2;								// 開始位置
		liX = D_ON;								// 横
	}
	else {									// 次と不一致(縦)
		llPCnt = 3;								// パターン数
		liNo = 1;								// 開始位置
		liX = D_OFF;							// 縦
	}

	// ２文字目以降
	for (i = liNo; i < liMCnt; i++) {
		if (lc1Mass[i] == lc1Mass[i + 1]) {		// 次と一致(横)
			if (liX == D_ON) {						// 前回横
				llPCnt = llPCnt * 3 % D_MOD;			// パターン数
			}
			else {									// 前回縦
				llPCnt = llPCnt * 2 % D_MOD;			// パターン数
			}
			liX = D_ON;								// 横
			i++;									// １つ次へ
		}
		else {									// 次と不一致(縦)
			if (liX == D_OFF) {						// 前回縦
				llPCnt = llPCnt * 2 % D_MOD;			// パターン数
			}
			liX = D_OFF;							// 縦
		}
	}

	// 結果セット
	sprintf(lc1Out, "%lld\n", llPCnt);

	// 結果表示
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpA);
	if (strcmp(lc1Buf, lc1Out)) {
		siRes = -1;
	}
#else
	printf("%s", lc1Out);
#endif

	// テストファイルクローズ
#ifdef D_TEST
	fclose(szpFpT);
	fclose(szpFpA);
#endif

	// テスト結果
#ifdef D_TEST
	if (siRes == 0) {
		printf("OK %d\n", piTNo);
	}
	else {
		printf("NG %d\n", piTNo);
	}
#endif

	return 0;
}

