class Dfs(val n: Int, val s1: List<Char>, val s2: List<Char>) {
    fun dfs(i: Int, count: Long, numFreeColors: Int): Long {
        if(i >= n) return count
        else {
            if(s1[i] == s2[i]) { // 縦に並んでいる時
                val currentFreeColors = when(numFreeColors) {
                    3 -> 3
                    2 -> 2
                    else -> 1
                }
                val nextCount = (count * currentFreeColors) % MOD
                return dfs(i+1, nextCount,  2) 
            } else { // 横に並んでいる時
                val currentFreeColors = when(numFreeColors) {
                    3 -> 6
                    2 -> 2
                    else -> 3
                }
                val nextCount = (count * currentFreeColors) % MOD
                return dfs(i+2, nextCount, 1)
            }
        }
    }

}


