		int n=scanner.nextInt();
		String[] s1=(scanner.next()+"1").split("");
		String[] s2=scanner.next().split("");
		List<Boolean>list=new ArrayList<>();
		int cnt=0;
		String pre=s1[0];
		for(int i=1;i<n+1;i++){
			String now=s1[i];
			if(now.equals(pre)){
				cnt++;
			}else{
				if(cnt==0){
					list.add(true);
				}else{
					list.add(false);
				}
				cnt=0;
			}
			pre=now;
		}
		int mod=1000000007;
		long p=list.get(0)?3:6;
		boolean x=list.get(0);
		for(int i=1;i<list.size();i++){
			boolean y=list.get(i);
