						ans = 3;
						f = 1;
					} else {
						ans = 3 * 2;
						f = 2;
						i++;
					}
				} else if(f == 1) {
					if(U[i] == D[i]) {
						ans = (ans * 2) % MOD;
					} else {
						ans = (ans * 2) % MOD;
						f = 2;
						i++;
					}
				} else {
					if(U[i] == D[i]) {
						f = 1;
					} else {
						ans = (ans * 3) % MOD;
						i++;
					}
				}
			}
        	prn(ans);
        }

