    static void solve() {
        int N = sc.nextInt();
        String S1 = sc.next();
        String S2 = sc.next();
        List<Integer> s = new ArrayList<>();
        long dp;
        for (int i = 0; i < N;) {
            if (S1.charAt(i) != S2.charAt(i)) {
                s.add(0);
                i += 2;
            } else {
                s.add(1);
                i += 1;
            }
        }
        if (s.get(0) == 0) {
            dp = 6;
        } else {
            dp = 3;
        }
        for (int i = 1; i < s.size(); i++) {
            if (s.get(i - 1) == 0 && s.get(i) == 0) {
                dp *= 3;
                dp %= MOD;
            } else if (s.get(i - 1) == 1 && s.get(i) == 0) {
                dp *= 2;
                dp %= MOD;
            } else if (s.get(i - 1) == 1 && s.get(i) == 1) {
                dp *= 2;
                dp %= MOD;
            }
        }
