			}else{				//今、縦型
				if(S1.charAt(i) == S1.charAt(i+1)){
					ans *= 2L;
					form = 2;
					i++;

				}else{
					ans *= 2L;
					form = 1;
				}
			}
			ans %=(long)mod;
		}


		System.out.println(ans);


	}
}

