                }else {
                    ans = 6;
                    i++;
                    before = 2;
                }
            }else {
                if(dm[0][i] == dm[1][i]) {
                    ans = (ans % mod) * (long)(before == 1 ? 2 : 1);
                    before = 1;
                }else {
                    ans = (ans % mod) * (long)(before == 1 ? 2 : 3);
                    i++;
                    before = 2;
                }
            }
        }
        System.out.println(ans % mod);
    }
