		}
		for (; index < n;) {
			if (index < n - 1 && s[index].equals(s[index + 1])) {
				if (before) {
					c = c * 3 % mod;
				}
				else {
					c = c * 2 % mod;
				}
				index += 2;
				before = true;
			}
			else {
				if (!before) {
					c *= 2 % mod;
				}
				index++;
				before = false;
			}
		}
