public class Main {
  enum Type {
    // bb
    // cc
    H,

    // a
    // a
    V
  }

  private static long solve(int n, char[][] ss) {
    List<Type> types = new ArrayList<>();
    int index = 0;
    while (index < n) {
      if (ss[0][index] == ss[1][index]) {
        types.add(Type.V);
        index += 1;
      } else {
        types.add(Type.H);
        index += 2;
      }
    }

    ModCalculator mc = new ModCalculator(1_000_000_007L);
    long answer;
    if (types.get(0) == Type.H) {
      answer = 6;
    } else {
      answer = 3;
    }

    for (int i = 1; i < types.size(); i++) {
      Type prev = types.get(i - 1);
      Type current = types.get(i);
      //aabb aabb aacc
      //bbaa bbcc bbaa
      if (prev == Type.H && current == Type.H) {
        answer = mc.mul(answer, 3);
      } else if (prev == Type.H && current == Type.V) {
        answer = mc.mul(answer, 1);
      } else if (prev == Type.V && current == Type.H) {
        answer = mc.mul(answer, 2);
      } else {  // prev == Type.V && current == Type.V
        answer = mc.mul(answer, 2);
      }
    }
    return answer;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    char[][] ss = reader.nextCharArray(2);
    out.println(solve(n, ss));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

