/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DColoringDominoes solver = new DColoringDominoes();
        solver.solve(1, in, out);
        out.close();
    }

    static class DColoringDominoes {
        static final int MOD = (int) 1e9 + 7;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            String S1 = in.nextString();
            String S2 = in.nextString();

            long ans = 0;
            int[] dom = new int[N + 10];
            int index = 0;
            for (int i = 0; i < N; i++) {
                if (S1.charAt(i) == S2.charAt(i)) {
                    dom[index] = 1;
                } else {
                    dom[index] = 2;
                    i++;
                }
                index++;
            }

            if (dom[0] == 1) {
                ans = 3;
            } else if (dom[0] == 2) {
                ans = 6;
            }

            for (int i = 1; dom[i] != 0; i++) {
                //if i-1 has one vertical domino, then doesn't matter whether i has vertical or
                //horizontal domino, we can chose other 2 colors
                if (dom[i - 1] == 1) {
                    ans = ans * 2;
                }
                //if i-1 has 2 horizontal colors, then selecting one vertical color for i doesn't
                //increase the count, as there is only 1 color. However, we can have 3 combinations
                //for 2 horizontal next dominos in i'th pos
                else if (dom[i - 1] == 2) {
                    if (dom[i] == 2) {
                        ans = ans * 3;
                    }
                }
                ans = ans % MOD;
            }
            out.println(ans);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }

    }
}

