            if(array[1][i] == array[1][i + 1]){
                str += 'Y';
                ++i;
                continue;
            }
            else str += 'X';
            if(i == n - 1)str += 'X';
        }
        long ans;
        long mod = (long)1E9 + 7;
        if(str.charAt(0) == 'X')
            ans = 3;
        else ans = 6;
