            if(str.charAt(i - 1) == 'X' && str.charAt(i) == 'Y')ans *= 2;
            if(str.charAt(i - 1) == 'X' && str.charAt(i) == 'X')ans *= 2;
            if(str.charAt(i - 1) == 'Y' && str.charAt(i) == 'Y')ans *= 3;
            while(ans >= mod)ans -= mod;
        }
        System.out.println(ans);
    }
