class Simple
{
    int N;
    string S1, S2;
    enum Block{
        Vertical,
        Horizontal
    }
    void Solve() {
        //input
        N = io.Int;
        S1 = io.String;
        S2 = io.String;
        //cal
        var mod =1000000007;
        var blockStatus = new Queue<Block>();
        var reS1 = S1.Distinct().ToArray();
        var reS2 = S2.Distinct().ToArray();
        Func<int, bool> isVertical = (index) 
            => reS1[index] == reS2[index];
        for (int i = 0; i < reS1.Count(); ++i) {
            if (isVertical(i)) {
                blockStatus.Enqueue(Block.Vertical);
            } else {
                blockStatus.Enqueue(Block.Horizontal);
            }
        }
        var preStatus = blockStatus.Dequeue();
        var ans = preStatus == Block.Vertical ? 3L : 6L;

        while (blockStatus.Count() > 0) {
            var curStatus = blockStatus.Dequeue();
            if (preStatus == Block.Horizontal &&
                curStatus == Block.Vertical) {
                //ans = ans * 1
            } else if (preStatus == Block.Horizontal &&
                       curStatus == Block.Horizontal) {
                ans = (ans * 3) % mod;
            } else {
                ans = (ans * 2) % mod;
            }
            preStatus = curStatus;
        }
        //ret
        WriteLine(ans);
    }

    SimpleIO io = new SimpleIO();
    public static void Main(string[] args) => new Simple().Stream();
    private void Stream() {
        //var exStdIn = new System.IO.StreamReader("stdin.txt");
        //SetIn(exStdIn);
        Solve();
        io.Flush();
    }
}
