using System;

namespace ABC071D
{
    class Program
    {
        static readonly int PREV_LAND = 1;
        static readonly int PREV_PORT = 2;
        static readonly int MOD = 1000000007;

        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            string S1 = Console.ReadLine();
            string S2 = Console.ReadLine();

            long res;
            int cur, prev;

            if(S1[0] == S2[0])
            {
                res = 3;
                cur = 1;
                prev = PREV_PORT;
            }
            else
            {
                res = 6;
                cur = 2;
                prev = PREV_LAND;
            }

            while (cur < N)
            {
                if (prev == PREV_PORT)
                {
                    if (S1[cur] == S2[cur])
                    {
                        res = (res * 2) % MOD;
                        cur += 1;
                        prev = PREV_PORT;
                    }
                    else
                    {
                        res = (res * 2) % MOD;
                        cur += 2;
                        prev = PREV_LAND;
                    }
                }
                else if (prev == PREV_LAND)
                {
                    if (S1[cur] == S2[cur])
                    {
                        // res = (res * 1) % MOD;
                        cur += 1;
                        prev = PREV_PORT;
                    }
                    else
                    {
                        res = (res * 3) % MOD;
                        cur += 2;
                        prev = PREV_LAND;
                    }
                }
                else
                {
                    throw new Exception();
                }
            }

            Console.WriteLine(res);
        }
    }
}

