				if(i == n -1 || s[i] != s[i + 1])
				{
					ans *= 3 - before;
					before = 1;
					i++;
				}
				else
				{
					if (before == 0) ans *= 6;
					else if (before == 1) ans *= 2;
					else ans *= 3;
					before = 2;
					i += 2;
				}
			}
			Console.WriteLine(ans);
		}

