                    if (prev < 0) sum *= 6;
                    else if (prev == 0) sum *= 2;
                    else if (prev == 1) sum *= 3;

                    i++;
                    prev = 1;
                }

                sum %= MOD;
            }

            Console.WriteLine(sum);
        }

