    public class Program {
        public static void Main (string[] args) {
            var N = ReadInt ();
            var S1 = Console.ReadLine ();
            var S2 = Console.ReadLine ();
            var IsTate = makeIsTateDominoForIndex (S1, S2);
            long ans = IsTate (0) ? 3 : 3 * 2;
            var i = IsTate (0) ? 1 : 2;
            while (i < N) {
                if (IsTate (i)) {
                    if (IsTate (i - 1)) {
                        ans *= 2;
                    }
                    i += 1;
                } else {
                    if (IsTate (i - 1)) {
                        ans *= 2;
                    } else {
                        ans *= 3;
                    }
                    i += 2;
                }
            }
            Print (ans % 1000000007);
        }

        public static Func<int, bool> makeIsTateDominoForIndex (string s1, string s2) {
            return (i) => s1[i] == s2[i];
        }
    }

