		{
			ans = 3;
			i = 1;
			//tate
			tateyoko = 0;
		}
		else
		{
			ans = 6;
			i = 2;
			//yoko
			tateyoko = 1;
		}

		while(i < N)
		{
			if(S1[i] == S2[i])
			{
				//縦
				if(tateyoko == 0)
				{
					//前が縦
					ans = ans * 2 % M;
				}
				else
				{
					//前が横
				}
				i++;
				tateyoko = 0;
			}
			else
			{
				//横
				if(tateyoko == 0)
				{
					//前が縦
					ans = ans * 2 % M;
