using System;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;

namespace NotFounds
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            new Program().Solve(new ConsoleInput(Console.In, ' '));
            Console.Out.Flush();
        }

        public void Solve(ConsoleInput cin)
        {
            const int MOD = 1000000007;

            var N = cin.ReadInt;
            var S = cin.ReadStrArray(2);
            var l = S[0].Length;
            var ans = 1L;
            var last = new char[] { S[0][0], S[1][0] };
            for (int i = 0; i < l; ++i)
            {
                if (S[0][i] != S[1][i])
                {
                    if (i == 0) { ans = 6; i++; continue; }
                    if (last[0] == last[1])
                    {
                        // | |[  ]
                        // | |[  ]

                        ans = (ans * 2) % MOD;
                    }
                    else
                    {
                        //  ][  ]
                        //  ][  ]

                        ans = (ans * 3) % MOD;
                    }
                    i++;
                }
                else
                {
                    if (i == 0) { ans = 3; continue; }
                    if (last[0] == last[1])
                    {
                        // | | |
                        // | | |

                        ans = (ans * 2) % MOD;
                    }
                    else
                    {
                        // ]| |
                        // ]| |

                        ans = (ans * 1) % MOD;
                    }
                }
                last[0] = S[0][i];
                last[1] = S[1][i];
            }
            WriteLine(ans);
        }
    }

    public static class Extensions
    {
        public static string Reverse(this string sourse)
        {
            char[] chrAry = sourse.ToCharArray();
            Array.Reverse(chrAry);
            return new string(chrAry);
        }
    }

    public class ConsoleInput
    {
        private readonly System.IO.TextReader _stream;
        private char _separator = ' ';
        private Queue<string> inputStream;
        public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
        {
            this._separator = separator;
            this._stream = stream;
            inputStream = new Queue<string>();
        }
        public string Read
        {
            get
            {
                if (inputStream.Count != 0) return inputStream.Dequeue();
                string[] tmp = _stream.ReadLine().Split(_separator);
                for (int i = 0; i < tmp.Length; ++i)
                    inputStream.Enqueue(tmp[i]);
                return inputStream.Dequeue();
            }
        }
        public string ReadLine { get { return _stream.ReadLine(); }}
        public int ReadInt { get { return int.Parse(Read); }}
        public long ReadLong { get { return long.Parse(Read); }}
        public double ReadDouble { get { return double.Parse(Read); }}
        public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret;}
        public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret;}
        public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret;}
        public void ReadIntArrays(long N, out int[] A, out int[] B) { A = new int[N]; B = new int[N]; for (long i = 0; i < N; ++i) { A[i] = ReadInt; B[i] = ReadInt; }}
    }
}

