    public static void Main(string[] args)
    {
        var N = Console.ReadLine().ToInt32();
        var S1 = Console.ReadLine();
        var S2 = Console.ReadLine();
        var grid = new char[2,N];

        for (int i = 0; i < N; i++)
        {
            grid[0, i] = S1[i];
        }
        for (int i = 0; i < N; i++)
        {
            grid[1, i] = S2[i];
        }
        var timesLs = new List<long>();
        var isX = false;
        for (int i = 0; i < N; i++)
        {
            if (grid[0,i] == grid[1, i])
            {
                if (i == 0)
                {
                    timesLs.Add(3);
                    isX = true;
                }
                else
                {
                    if (isX)
                    {
                        timesLs.Add(2);
                    }
                    else
                    {
                        timesLs.Add(1);
                    }
                    isX = true;
                }
            }
            else
            {
                if (i == 0)
                {
                    timesLs.Add(6);
                    isX = false;
                }
                else
                {
                    if (isX)
                    {
                        timesLs.Add(2);
                    }
                    else
                    {
                        timesLs.Add(3);
                    }
                    isX = false;
                }
                i++;
            }
        }
        Console.WriteLine(timesLs.Aggregate((x,y) => (x * y % 1000000007)));
        Console.ReadLine();
    }



