        public static void Main(string[] args)
        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }

        static void Solve()
        {
            var N = Sarray()[0];
            var S1 = ReadLine();
            var S2 = ReadLine();
            var ans = 1L;
            var pre = -1;//0:縦、1:横
            for (var i = 0; i < N; ++i)
            {
                if (S1[i] == S2[i])//縦に並ぶ
                {
                    if (pre == -1)//初期値
                        ans = 3;
                    else if (pre == 0)//縦→縦なら2通り
                        ans = ans * 2 % Mod;
                    else//横→縦なら固定
                        ans = ans;
                    pre = 0;
                }
                else//横に並ぶ
                {
                    if (pre == -1)//初期値は3*2
                        ans = 3 * 2;
                    else if (pre == 0)//縦→横なら2通り
                        ans = ans * 2 % Mod;
                    else//横→横なら3通り
                        ans = ans * 3 % Mod;
                    pre = 1;
                    ++i;
                }
            }
            WriteLine(ans);
        }

        static long Mod = (long)1e9 + 7;
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
