		isBeforeVertical = true
	} else {
		// 先頭が横
		ans *= 6
		index = 2
		isBeforeVertical = false
	}

	for index < n {
		var isVertical bool
		if ss[0][index] == ss[1][index] {
			// 縦
			isVertical = true
			index++
		} else {
			// 横
			isVertical = false
			index += 2
		}

		if !isBeforeVertical && isVertical {
			ans *= 1
		} else if !isBeforeVertical && !isVertical {
			ans *= 3
			ans %= mod
		} else {
			ans *= 2
			ans %= mod
		}

		isBeforeVertical = isVertical
	}

	fmt.Println(ans)
