func checkVertical(s [][]byte, i int) bool {
	return s[0][i] == s[1][i]
}

func main() {
	defer stdout.Flush()

	n := readInt()
	s := make([][]byte, 2)
	s[0] = []byte(readString())
	s[1] = []byte(readString())

	var ans int
	var prevVertical bool
	p := 1000000007
	i := 0
	if checkVertical(s, i) {
		ans = 3
		i++
		prevVertical = true
	} else {
		ans = 6
		i += 2
		prevVertical = false
	}
	for i < n {
		curVertical := checkVertical(s, i)
		if prevVertical {
			ans = ans * 2 % p
		} else {
			if !curVertical {
				ans = ans * 3 % p
			}
		}

		if curVertical {
			i++
		} else {
			i += 2
		}
		prevVertical = curVertical
	}

	println(ans)
}

