import "fmt"

const MOD = 1000000007

func main() {
    var n int
    var s1, s2 string
    var ans, preState, index int
    fmt.Scan(&n)
    fmt.Scan(&s1)
    fmt.Scan(&s2)
    if s1[0] == s2[0] {
        ans = 3
        preState = 0
        index = 1
    } else {
        ans = 6
        preState = 1
        index = 2
    }

    for index < n {
        if s1[index] == s2[index] {
            if preState == 0 {
                ans *= 2
            } else {
                ans *= 1
            }
            preState = 0
            index += 1

        } else {
            if preState == 0 {
                ans *= 2
            } else {
                ans *= 3
            }
            preState = 1
            index += 2
        }
        ans %= MOD
    }
    fmt.Println(ans)
}

