	S1 := getString()
	S2 := getString()

	relations := make(map[string]map[string]struct{})

	for i := 0; i < N-1; i++ {
		s1l := string(S1[i])
		s1r := string(S1[i+1])
		s2l := string(S2[i])
		s2r := string(S2[i+1])

		if _, exists := relations[s1l]; !exists {
			relations[s1l] = make(map[string]struct{})
		}
		if _, exists := relations[s1r]; !exists {
			relations[s1r] = make(map[string]struct{})
		}
