			relations[s2r] = make(map[string]struct{})
		}

		if s1l != s1r {
			relations[s1l][s1r] = struct{}{}
			relations[s1r][s1l] = struct{}{}
		}

		if s2l != s2r {
			relations[s2l][s2r] = struct{}{}
			relations[s2r][s2l] = struct{}{}
		}

