	for c1, relation := range relations {
		used := make(map[int]struct{})
		for c2 := range relation {
			color, exists := colors[c2]
			if exists {
				used[color] = struct{}{}
			}
		}
		for i := 3; i > 0; i-- {
			_, exists := used[i]
			if !exists {
				colors[c1] = i
				break
			}
		}
	}

	//fmt.Println(colors)

	result := 1
	if len(colors) == 0 {
		result = 3
	} else {
		for _, color := range colors {
			result = calcMod(result * color)
		}
	}
	fmt.Println(result)
}

