const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	S1 := sc.nextStr()
	S2 := sc.nextStr()
	p := []int{}
	for i := 0; i < N; i++ {
		if S1[i] == S2[i] {
			p = append(p, 0)
		} else {
			p = append(p, 1)
			i++
		}
	}
	ans := 1
	for i := 0; i < len(p); i++ {
		if i == 0 {
			if p[i] == 0 {
				ans *= 3
				ans %= MOD
			} else {
				ans *= (3 * 2)
				ans %= MOD
			}
		} else {
			if p[i-1] == 1 && p[i] == 1 {
				ans *= 3
				ans %= MOD
			} else if p[i-1] == 1 && p[i] == 0 {
				ans *= 1
				ans %= MOD
			} else if p[i-1] == 0 && p[i] == 0 {
				ans *= 2
				ans %= MOD
			} else {
				ans *= 2
				ans %= MOD
			}
		}
	}

	fmt.Fprintln(wtr, ans)
}

