func solve() {
	n := ri()

	s := make([]string, 2)
	for i := 0; i < 2; i++ {
		s[i] = rs()
	}

	t := make([][]byte, n)
	for i := 0; i < n; i++ {
		t[i] = make([]byte, 2)
	}
	for i := range t {
		for j := range t[i] {
			t[i][j] = s[j][i]
		}
	}

	var ans int
	if t[0][0] == t[0][1] {
		ans = 3
	} else {
		ans = 6
	}

	for i := 1; i < n; i++ {
		switch {
		case t[i-1][0] == t[i][0] && t[i-1][1] == t[i][1]:
		case t[i-1][0] == t[i-1][1] && t[i][0] == t[i][1]:
			ans *= 2
		case t[i-1][0] == t[i-1][1]:
			ans *= 2
		case t[i][0] == t[i][1]:
		default:
			ans *= 3
		}
		ans %= mod
	}
	pln(ans)
}

