	ans := 1
	prevUp := true
	for i := 0; i < len(s1); i++ {
		if i == 0 {
			if s1[i] == s2[i] {
				ans *= 3
				prevUp = true
			} else {
				ans *= 6
				i++
				prevUp = false
			}
		} else {
			if s1[i] == s2[i] {
				if prevUp {
					ans *= 2
				} else {
					ans *= 1
				}
				prevUp = true
			} else {
