	fmt.Fscan(r, &ss[1])

	mod := 1000000007

	if n == 1 {
		fmt.Println(3)
		return
	}

	ans := 1
	index := 0
	var isBeforeVertical bool
	if ss[0][0] == ss[1][0] {
		// 先頭が縦
		ans *= 3
		index = 1
		isBeforeVertical = true
	} else {
		// 先頭が横
		ans *= 6
		index = 2
		isBeforeVertical = false
	}

	for index < n {
		var isVertical bool
		if ss[0][index] == ss[1][index] {
			// 縦
			isVertical = true
			index++
		} else {
			// 横
			isVertical = false
			index += 2
		}

		if !isBeforeVertical && isVertical {
			ans *= 1
		} else {
			ans *= 2
			ans %= mod
		}

		isBeforeVertical = isVertical
	}

	fmt.Println(ans)
