                SS[j] = [j-1];
            } else {
                SS[j] = [j-2, j-1];
            }
        } else {
            if (i == 0) {
                SS[j++] = [];
                SS[j] = [j-1];
            } else if (s1[i-1] == s2[i-1]) {
                SS[j] = [j-1];
                ++j;
                SS[j] = [j-2, j-1];
            } else {
                SS[j] = [j-2];
                ++j;
                SS[j] = [j-2, j-1];
            }
            ++i;
        }
        ++j;
    }

    long[immutable(dchar)[]][52] memo;

    long solve(int i) {
        if (i == n) return 1;

        immutable(dchar)[] key;
        foreach (j; (i-2 < 0 ? 0 : i-2)..i) key ~= CS[j];
