            CS[i] = 'G';
            ret = ret + solve(i+1) % N;
        }
        if (cls & 0x001) {
            CS[i] = 'B';
            ret = ret + solve(i+1) % N;
        }
        return memo[i][key] = ret;
    }

    writeln(solve(0));
}

