auto solve( dchar[] s1, dchar[] s2 )
{
	const MOD = 10L ^^ 9 + 7;
	auto ans = 0L;
	auto i = 0L;
	auto v = false;

	// 初手
	if( s1[ i ] == s2[ i ] )
	{
		// 縦置きの場合
		ans = 3;
		i++;
		v = true;
	}
	else
	{
		// 横置きの場合
		ans = 6;
		i += 2;
		v = false;
	}

	// 2列目以降
	while( i < s1.length )
	{
		if( s1[ i ] == s2[ i ] )
		{
			// 縦置きの場合
			if( v ) ans = ans * 2 % MOD;		// 縦置き⇒縦置き
//			else    ans = ans * 1 % MOD;		// 横置き⇒縦置き
			i++;
			v = true;
		}
		else
		{
			// 横置きの場合
			if( v ) ans = ans * 2 % MOD;		// 縦置き⇒横置き
			else    ans = ans * 3 % MOD;		// 横置き⇒横置き
			i += 2;
			v = false;
		}
	}
	return ans;
}

