def D_Coloring_Dominoes(N, S1, S2):
    from collections import deque
    S1, S2 = deque(S1), deque(S2)

    def decisionBlock(s1, s2):
        # s1,s2の先頭ドミノが縦に1個か横に2個のブロックになっているかを判定
        if s1[0] == s2[0]:
            block = 'X'  # 解説の"X","Y"の決め方を踏襲
            s1.popleft()
            s2.popleft()
        elif s1[0] == s1[1] and s2[0] == s2[1]:
            block = 'Y'
            s1.popleft()
            s1.popleft()
            s2.popleft()
            s2.popleft()
        else:
            tmp = 'NotBlock'  # 入力の制約上ここに来ないはず
        return block

    combination = 0

    # 最左端のブロックの塗り方の組み合わせを算出しておく
    firstblock = decisionBlock(S1, S2)
    if firstblock == 'X':
        combination += 3
    else:
        combination += 6

    # 残りのブロックの塗り方の組み合わせを求める
    leftblock = firstblock
    while S1 != deque([]):
        block = decisionBlock(S1, S2)
        if (leftblock, block) == ('X', 'X'):
            combination *= 2
        elif (leftblock, block) == ('Y', 'X'):
            combination *= 1
        elif (leftblock, block) == ('X', 'Y'):
            combination *= 2
        elif (leftblock, block) == ('Y', 'Y'):
            combination *= 3
        leftblock = block
    return combination%(10**9+7)

