def slv(N, S1, S2):
    ans = 0
    MOD = 1000000007

    if S1[0] == S2[0]:
        ans = 3
        i = 1
        p = 0
    else:
        ans = 6
        i = 2
        p = 1

    while i < N:
        if p == 0:
            if S1[i] == S2[i]:
                ans *= 2
                i += 1
                p = 0
            else:
                ans *= 2
                i += 2
                p = 1
        else:
            if S1[i] == S2[i]:
                p = 0
                i += 1
            else:
                ans *= 3
                i += 2
                p = 1
        ans %= MOD

    return ans


