use std::cmp::*;
use std::collections::*;
use std::f64::consts::*;

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

const MOD: u64 = 1_000_000_000 + 7;
fn main() {
    input! {
        n: usize,
        mut s1: chars,
        mut s2: chars,
    }
    let mut cur = 0;
    let mut ans = 1u64;
    let mut tate = true;

    if n == 1 {
        ans *= 3;
        ans %= MOD;
        cur += 1;
    }

    while cur < n - 1 {
        if cur == 0 {
            if s1[cur] == s1[cur + 1] {
                ans *= 6;
                ans %= MOD;
                cur += 2;
                tate = false;
            } else {
                ans *= 3;
                ans %= MOD;
                cur += 1;
                tate = true;
            }
            continue;
        }
        match (tate, s1[cur] == s1[cur + 1]) {
            (true, true) => {
                ans *= 2;
                ans %= MOD;
                cur += 2;
                tate = false;
            }
            (true, false) => {
                ans *= 2;
                ans %= MOD;
                cur += 1;
                tate = true;
            }
            (false, true) => {
                ans *= 3;
                ans %= MOD;
                cur += 2;
                tate = false;
            }
            (false, false) => {
                cur += 1;
                tate = true;
            }
        }
    }
    println!("{}", ans % MOD);
}

