fn solve(s1: String, s2: String) -> usize {
    const M: usize = 1000000007;
    let (s1, s2) = (s1.as_bytes(), s2.as_bytes());

    let mut result = 6666666666;
    let mut skip = false;
    let mut last_vert = None;
    for (c1, c2) in s1.iter().zip(s2.iter()) {
        if skip {
            skip = false;
            last_vert = Some(false);
            continue;
        }
        if last_vert == Some(true) && c1 == c2 {
            result = (2 * result) % M;
        } else if last_vert == Some(true) && c1 != c2 {
            result = (2 * result) % M;
            skip = true;
        } else if last_vert == Some(false) && c1 == c2 {
            last_vert = Some(true);
        } else if last_vert == Some(false) && c1 != c2 {
            result = (3 * result) % M;
            skip = true;
        } else if last_vert == None && c1 == c2 {
            result = 3;
            last_vert = Some(true);
        } else if last_vert == None && c1 != c2 {
            result = 6;
            skip = true;
        }
    }
    result
}


