fn solve(ss: Vec<char>) -> u64 {
    let n = ss.len();

    let md = 1000000007;
    let mut pos = 0;
    let mut state = 0;
    let mut ret = 1;

    if n == 1 {
        return 3
    }

    if ss[0] == ss[1] {
        ret = 6;
        state = 2;
        pos += 2;
    } else {
        ret = 3;
        state = 1;
        pos += 1;
    }

    while pos < n {
        if pos < n-1 && ss[pos] == ss[pos+1] {
            if state == 1 {
                ret = (ret * 2) % md;
                state = 2;
            } else {
                ret = (ret * 3) % md;
            }
            pos += 2;
        } else {
            if state == 1 {
                ret = (ret * 2) % md;
            } else {
                state = 1;
            }
            pos += 1;
        }
    }

    ret
}

fn main() {
    read_line!();

    let ss = read_line!();
    println!("{}", solve(ss.chars().collect()));
}

