fn main() {
	input! {
		n: usize,
		s1: Chars,
		s2: Chars,
	}

	let mut index = 0usize;
	let mut ans: usize;
	let mut prev;
	// 最初
	if s1[index] == s2[index] {
		// 縦型
		ans = 3;
		index += 1;
		prev = 0;
	}
	else {
		// 横型
		ans = 6;
		index += 2;
		prev = 1;
	}
	loop {
		if index >= n {
			break;
		}
		if s1[index] == s2[index] {
			// 今回は縦型
			if prev == 0 {
				// 前は縦型
				ans = ans * 2 % 1000000007;
			}
			else {
				// 前は横型
				//ans = ans * 1 % 1000000007;
			}
			index += 1;
			prev = 0;
		}
		else {
			// 今回は横型
			if prev == 0 {
				// 前は縦型
				ans = ans * 2 % 1000000007;
			}
			else {
				// 前は横型
				ans = ans * 3 % 1000000007;
			}
			index += 2;
			prev = 1;
		}
	}
	println!("{}", ans);
}

use proconio::input;
use proconio::marker::Chars;

fn main() {
    input! {
        n: usize,
        s1: Chars,
        s2: Chars,
    }

    let m = 1000000007usize;

    let mut comb;
    let mut direction;

    if s1[0] == s2[0] {
        comb = 3;
        direction = Direction::Vertical;
    } else {
        comb = 6;
        direction = Direction::Horizontal;
    };

    let mut i = 1;
    if s1[0] != s2[0] {
        i = 2;
    }
    while i < n {
        if s1[i] == s2[i] {
            match direction {
                Direction::Horizontal => comb = comb * 1 % m,
                Direction::Vertical => comb = comb * 2 % m,
            }
            direction = Direction::Vertical;
        } else {
            match direction {
                Direction::Horizontal => comb = comb * 3 % m,
                Direction::Vertical => comb = comb * 2 % m,
            }
            i += 1;
            direction = Direction::Horizontal;
        }
        i += 1;
    }
    println!("{}", comb);
}

enum Direction {
    Vertical,
    Horizontal,
}

use std::io::*;
use std::str::FromStr;

pub fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MOD: i64 = 1000000007;

fn main() {
    let n: usize = read();
    let s1: String = read();
    let s2: String = read();

    let sc1: Vec<char> = s1.chars().collect();
    let sc2: Vec<char> = s2.chars().collect();

