    }
    let mut t = 1;
    let mut p = 0;
    let mut i = 0;
    while i < n {
        if s1[i] == s2[i] {
            t *= 3 - p;
            i += 1;
            p = 1;
        } else {
            t *= match p {
                0 => 6,
                1 => 2,
                2 => 3,
                _ => panic!(),
            };
            i += 2;
            p = 2;
        }
    }
    println!("{}", t % MOD);
}
